from collections import deque

def list_components(grid):
    visited = set()
    comps = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            color = grid[r][c]
            if color != 0 and color != 8 and (r,c) not in visited:
                q = deque([(r,c)])
                comp = []
                while q:
                    cr, cc = q.popleft()
                    if (cr, cc) in visited or grid[cr][cc] != color:
                        continue
                    visited.add((cr, cc))
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr,nc) not in visited:
                                q.append((nr, nc))
                comps.append({'color': color, 'cells': set(comp)})
    return comps

